fun octets(s: String) = IntArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16) }

case("s30-1 offset function", instructionLimit = 1000000) {
  val initial_source =
      octets(
          "",
      )
  for (i in initial_source.indices step 4) setWord(
      "source",
      (0..3).fold(0) { v, j -> v or (initial_source[i + j] shl (8 * j)) },
      i,
  )
  val initial_destination =
      octets(
          "",
      )
  for (i in initial_destination.indices step 4) setWord(
      "destination",
      (0..3).fold(0) { v, j -> v or (initial_destination[i + j] shl (8 * j)) },
      i,
  )
  val initial_state =
      octets(
          "a5a5a5a5a5a5a5a5a5a5a5a5657870616e642033322d62797465206b000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f01000000000000090000004a00000000a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
      )
  for (i in initial_state.indices step 4) setWord(
      "state",
      (0..3).fold(0) { v, j -> v or (initial_state[i + j] shl (8 * j)) },
      i,
  )
  val initial_quad =
      octets(
          "a5a5a5a5a5a5a5a511111111a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a504030201a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5436f8d9ba5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a567452301a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
      )
  for (i in initial_quad.indices step 4) setWord(
      "quad",
      (0..3).fold(0) { v, j -> v or (initial_quad[i + j] shl (8 * j)) },
      i,
  )
  setWord("mode", 2)
  setWord("in_place", 0)
  setWord("length", 65.toInt())
  setWord("length", 0.toInt(), 4)
  setWord("status", -1)
  val saved = List(9) { 0x456789ab00000000L + it * 509 }
  for (i in 0..7) setRegister("s$i", saved[i])
  setRegister("fp", saved[8])
  setRegister("sp", 0x7fff0000L)
  setRegisterToDataAddress("a0", "state", 12L)
  setRegisterToDataAddress("a1", "destination", 4L)
  setRegisterToTextAddress("ra", "function_return")
  startAt("chacha_block_msa")
  val root = readDataAddress("source")
  val size = (readDataAddress("status") + 4 - root).toInt()
  val before = readBytes("source", size)
  val trace = traceMemoryAccesses(root, size, maxAccesses = 200000)
  val allowedReads: List<Pair<Long, Int>> =
      listOf(readDataAddress("state", 12L) to 64, readDataAddress("destination", 4L) to 64)
  val allowedWrites: List<Pair<Long, Int>> = listOf(readDataAddress("destination", 4L) to 64)
  fun fits(a: Long, n: Int, b: Long, s: Int) = a >= b && n <= s && a - b <= s.toLong() - n
  runUntil("after_msa_repeat")
  expectCondition(
      readBytes("source", 4160)
          .contentEquals(
              octets(
                  "",
              ),
          ),
      "source matches independently modeled phase",
  )
  expectCondition(
      readBytes("destination", 4160)
          .contentEquals(
              octets(
                  "",
              ),
          ),
      "destination matches independently modeled phase",
  )
  expectCondition(
      readBytes("state", 128)
          .contentEquals(
              octets(
                  "a5a5a5a5a5a5a5a5a5a5a5a5657870616e642033322d62797465206b000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f01000000000000090000004a00000000a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
              ),
          ),
      "state matches independently modeled phase",
  )
  expectCondition(
      readBytes("quad", 96)
          .contentEquals(
              octets(
                  "a5a5a5a5a5a5a5a511111111a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a504030201a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5436f8d9ba5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a567452301a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
              ),
          ),
      "quad matches independently modeled phase",
  )
  expectRegister("sp", 0x7fff0000L - 0)
  expectRegister("t0", 0L)
  expectVectorLane("w0", 0, 32, 2205644971L)
  expectVectorLane("w0", 1, 32, 3795375971L)
  expectVectorLane("w0", 2, 32, 2793071134L)
  expectVectorLane("w0", 3, 32, 1498463023L)
  expectVectorLane("w4", 0, 32, 1634760805L)
  expectVectorLane("w4", 1, 32, 857760878L)
  expectVectorLane("w4", 2, 32, 2036477234L)
  expectVectorLane("w4", 3, 32, 1797285236L)
  expectVectorLane("w1", 0, 32, 3304247495L)
  expectVectorLane("w1", 1, 32, 4234328879L)
  expectVectorLane("w1", 2, 32, 2409634044L)
  expectVectorLane("w1", 3, 32, 1063176119L)
  expectVectorLane("w5", 0, 32, 50462976L)
  expectVectorLane("w5", 1, 32, 117835012L)
  expectVectorLane("w5", 2, 32, 185207048L)
  expectVectorLane("w5", 3, 32, 252579084L)
  expectVectorLane("w2", 0, 32, 861041090L)
  expectVectorLane("w2", 1, 32, 4069820915L)
  expectVectorLane("w2", 2, 32, 3938298108L)
  expectVectorLane("w2", 3, 32, 2196008637L)
  expectVectorLane("w6", 0, 32, 319951120L)
  expectVectorLane("w6", 1, 32, 387323156L)
  expectVectorLane("w6", 2, 32, 454695192L)
  expectVectorLane("w6", 3, 32, 522067228L)
  expectVectorLane("w3", 0, 32, 3516666548L)
  expectVectorLane("w3", 1, 32, 2957907678L)
  expectVectorLane("w3", 2, 32, 2659438795L)
  expectVectorLane("w3", 3, 32, 1312575650L)
  expectVectorLane("w7", 0, 32, 1L)
  expectVectorLane("w7", 1, 32, 150994944L)
  expectVectorLane("w7", 2, 32, 1241513984L)
  expectVectorLane("w7", 3, 32, 0L)
  runUntil("function_return")
  expectCondition(
      readBytes("source", 4160)
          .contentEquals(
              octets(
                  "",
              ),
          ),
      "source matches independently modeled phase",
  )
  expectCondition(
      readBytes("destination", 4160)
          .contentEquals(
              octets(
                  "",
              ),
          ),
      "destination matches independently modeled phase",
  )
  expectCondition(
      readBytes("state", 128)
          .contentEquals(
              octets(
                  "a5a5a5a5a5a5a5a5a5a5a5a5657870616e642033322d62797465206b000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f01000000000000090000004a00000000a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
              ),
          ),
      "state matches independently modeled phase",
  )
  expectCondition(
      readBytes("quad", 96)
          .contentEquals(
              octets(
                  "a5a5a5a5a5a5a5a511111111a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a504030201a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5436f8d9ba5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a567452301a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
              ),
          ),
